// Stamps and hotspots for RefDumpCollision.
//
// Stamps: the reference world is a normal small world; it has no land mines, gem sensors, spikes next to slopes, actuated
// platforms and so on in one place. To make every branch of the collision code reachable the harness writes a deterministic
// "garden" of tiles into an empty block of sky (found by scanning: no active tile and no liquid in the block plus 8 tiles
// around it). The garden is generated by System.Random(StampSeed):
//   block 96 x 54 tiles at (StampX, StampY); rows 0..13 are liquid pools (types water, lava, honey, shimmer; amounts 1..255);
//   rows 14..47 are a dense garden: each cell is empty (40%) or a tile whose type is 55% from a curated list of types the
//   collision code distinguishes (dirt, sand, glass, platforms 19 and 380, switches 135 210 442 443, cobweb 51, 229,
//   doors 10 388, spikes 48, cactus 80, 230, meteorite 37, hellstone 58, ...) and 45% uniform over all 754 tile types;
//   rows 45..47: "conveyor strip" (row 47: conveyor belts 421 / 422 in runs of 8, sloped at the ends, rows 45-46 air);
//   rows 48..53: "mine strip" (land mines every 3rd column in row 51 on a dirt floor in row 52);
//   slope 1..4 on 25% of the tiles, half brick on 8%, actuated off (inActive) on 6%, liquid (any type) on 15% of all cells.
//   frameX / frameY: platforms get frameX = 18 * (0..29), frameY from {0, 18, 36, 900}; 442 gets frameX = 22 * (0..3) + (0..1) * 0;
//   135 gets frameY = 18 * (0..7); other types frameX = 18 * (0..30), frameY = 18 * (0..8).
// Every stamped tile is written with all nine fields (wall 0). stamps.bin: "STMP" | i32 count | count x (i32 x, i32 y, 14 byte record).
using System;
using System.Collections.Generic;
using System.IO;
using System.Reflection;

static partial class RefDumpCollision
{
    const int StampSeed = 7771;
    const int SW = 96, SH = 54;
    static int StampX, StampY;
    class StampRec { public int X, Y; public byte[] Rec; }
    static List<StampRec> stampList;

    // curated tile types for the garden
    static readonly int[] StampTypes = { 1, 1, 1, 1, 2, 53, 54, 19, 19, 19, 19, 380, 135, 210, 442, 443, 51, 229, 10, 388, 48, 80, 230, 37, 58, 0, 4, 5, 15, 21, 11, 137, 311, 421, 422, 232, 190, 184, 160 };

    static void SetTileFields(int x, int y, byte[] rec)
    {
        object t = TileArr.GetValue(x, y);
        TileT.GetField("type").SetValue(t, (ushort)(rec[0] | (rec[1] << 8)));
        TileT.GetField("wall").SetValue(t, (ushort)(rec[2] | (rec[3] << 8)));
        TileT.GetField("liquid").SetValue(t, rec[4]);
        TileT.GetField("sTileHeader").SetValue(t, (ushort)(rec[5] | (rec[6] << 8)));
        TileT.GetField("bTileHeader").SetValue(t, rec[7]);
        TileT.GetField("bTileHeader2").SetValue(t, rec[8]);
        TileT.GetField("bTileHeader3").SetValue(t, rec[9]);
        TileT.GetField("frameX").SetValue(t, (short)(rec[10] | (rec[11] << 8)));
        TileT.GetField("frameY").SetValue(t, (short)(rec[12] | (rec[13] << 8)));
    }

    static bool BlockEmpty(int x0, int y0)
    {
        for (int x = x0 - 8; x < x0 + SW + 8; x++)
            for (int y = y0 - 8; y < y0 + SH + 8; y++)
            {
                if ((RdS(TileArr, x, y) & 0x20) != 0 || RdLiquid(TileArr, x, y) != 0) return false;
            }
        return true;
    }

    static void Stamps(out List<StampRec> list)
    {
        list = new List<StampRec>();
        StampY = 60;
        StampX = -1;
        for (int x = 300; x + SW + 8 < W; x += 8)
            if (BlockEmpty(x, StampY)) { StampX = x; break; }
        if (StampX < 0) throw new Exception("no empty block of sky found for the stamps");
        var rng = new Random(StampSeed);
        for (int dx = 0; dx < SW; dx++)
            for (int dy = 0; dy < SH; dy++)
            {
                int x = StampX + dx, y = StampY + dy;
                int type = 0; bool active = false; int slope = 0; bool half = false, inactive = false;
                int liquid = 0, liquidType = 0; int fx = 0, fy = 0;
                if (dy < 14)
                {
                    // pools: a few rectangles decided by the column / row cell
                    int pool = (dx / 12) * 7 + (dy / 7);
                    var pr = new Random(StampSeed * 31 + pool);
                    bool has = pr.Next(3) != 0;
                    int lt = pr.Next(4), amt = 1 + pr.Next(255);
                    if (has && (dy % 7) >= pr.Next(4)) { liquid = (rng.Next(4) == 0) ? 1 + rng.Next(255) : amt; liquidType = lt; }
                    if (rng.Next(14) == 0) { active = true; type = 1; slope = rng.Next(5); }
                }
                else if (dy >= 45 && dy <= 47)
                {
                    // "conveyor strip": rows 45-46 air, row 47 conveyor belts (421 / 422) in runs of 8 with sloped and half brick ends
                    if (dy == 47)
                    {
                        active = true; type = ((dx / 8) % 2 == 0) ? 421 : 422;
                        int e = dx % 8;
                        if (e == 0) slope = 1 + rng.Next(2); else if (e == 7) slope = 3 + rng.Next(2); else if (rng.Next(10) == 0) half = true;
                        if (rng.Next(30) == 0) inactive = true;
                    }
                }
                else if (dy >= 48)
                {
                    // "mine strip": land mines on a plain dirt floor with plain neighbours (the random garden below would make
                    // WorldGen.KillTile, called by Wiring.ExplodeMine, recurse until the stack overflows)
                    if (dy == 51 && dx % 3 == 0) { active = true; type = 210; }
                    else if (dy == 52) { active = true; type = 1; }
                }
                else
                {
                    if (rng.Next(100) >= 40)
                    {
                        active = true;
                        type = rng.Next(100) < 55 ? StampTypes[rng.Next(StampTypes.Length)] : rng.Next(754);
                        if (type == 0 && rng.Next(2) == 0) type = 1;
                        if (type == 210) type = 1;   // land mines only in the mine strip
                        int s = rng.Next(100);
                        if (s < 25) slope = 1 + rng.Next(4);
                        else if (s < 33) half = true;
                        if (rng.Next(100) < 6) inactive = true;
                        if (type == 19 || type == 380) { fx = 18 * rng.Next(30); int[] fys = { 0, 18, 36, 900 }; fy = fys[rng.Next(4)]; }
                        else if (type == 442) { fx = 22 * rng.Next(4); }
                        else if (type == 135) { fy = 18 * rng.Next(7); }   // frameY / 18 == 7 would make SwitchTiles call WorldGen.KillTile, which overflows the stack on the random garden
                        else { fx = 18 * rng.Next(31); fy = 18 * rng.Next(9); }
                    }
                }
                if (dy >= 14 && dy < 45 && rng.Next(100) < 15) { liquid = 1 + rng.Next(255); liquidType = rng.Next(4); }
                byte[] rec = new byte[RecordSize];
                Put16(rec, 0, active ? type : 0);
                Put16(rec, 2, 0);
                rec[4] = (byte)liquid;
                int s0 = (active ? 0x20 : 0) | (inactive && active ? 0x40 : 0) | (half && active ? 0x400 : 0) | ((active ? slope : 0) << 12);
                Put16(rec, 5, s0);
                rec[7] = (byte)(liquidType << 5);
                rec[8] = 0; rec[9] = 0;
                Put16(rec, 10, active ? fx : 0);
                Put16(rec, 12, active ? fy : 0);
                SetTileFields(x, y, rec);
                list.Add(new StampRec { X = x, Y = y, Rec = rec });
            }
        using (var fs = new FileStream(Path.Combine(OutDir, "stamps.bin"), FileMode.Create))
        {
            fs.Write(new byte[] { (byte)'S', (byte)'T', (byte)'M', (byte)'P' }, 0, 4);
            fs.Write(BitConverter.GetBytes(list.Count), 0, 4);
            foreach (StampRec s in list)
            {
                fs.Write(BitConverter.GetBytes(s.X), 0, 4);
                fs.Write(BitConverter.GetBytes(s.Y), 0, 4);
                fs.Write(s.Rec, 0, RecordSize);
            }
        }
    }

    // stamped active tiles of the given types (tile coordinates)
    static List<int[]> StampedOfType(params int[] types)
    {
        var l = new List<int[]>();
        foreach (StampRec s in stampList)
        {
            int ty = s.Rec[0] | (s.Rec[1] << 8);
            if ((s.Rec[5] & 0x20) != 0 && Array.IndexOf(types, ty) >= 0) l.Add(new int[] { s.X, s.Y });
        }
        return l;
    }

    // ---------------------------------------------------------------- hotspots (tile coordinates of interesting places in the real map)
    static List<int>[] Spots;   // each entry: x * H + y
    static string[] SpotNames = { "surface", "slope", "half", "platform", "liquidEdge", "lavaHoney", "cave", "spawn", "hurting", "stamp", "any" };
    static void AddSpot(int kind, int x, int y) { Spots[kind].Add(x * H + y); }

    static void BuildHotspots()
    {
        Spots = new List<int>[SpotNames.Length];
        for (int i = 0; i < Spots.Length; i++) Spots[i] = new List<int>();
        bool[] solid = (bool[])SF(MainT, "tileSolid");
        bool[] solidTop = (bool[])SF(MainT, "tileSolidTop");
        Type sets = T("Terraria.ID.TileID+Sets");
        bool[] platforms = (bool[])SF(sets, "Platforms");
        bool[] suffocate = (bool[])SF(sets, "Suffocate");
        bool[] hot = (bool[])SF(sets, "TouchDamageHot");
        bool[] bleeding = (bool[])SF(sets, "TouchDamageBleeding");
        int[] immediate = (int[])SF(sets, "TouchDamageImmediate");
        var r = new Random(StampSeed + 5);
        for (int x = 1; x < W - 1; x++)
        {
            bool surfaceDone = false;
            for (int y = 1; y < H - 41; y++)
            {
                ushort s = RdS(TileArr, x, y);
                bool active = (s & 0x20) != 0;
                ushort type = RdType(TileArr, x, y);
                byte liq = RdLiquid(TileArr, x, y);
                if (active && !surfaceDone && (solid[type] || solidTop[type])) { surfaceDone = true; AddSpot(0, x, y); }
                if (active && (s & 0x7000) != 0 && r.Next(3) == 0) AddSpot(1, x, y);
                if (active && (s & 0x400) != 0 && r.Next(2) == 0) AddSpot(2, x, y);
                if (active && platforms[type]) AddSpot(3, x, y);
                if (liq > 0 && RdLiquid(TileArr, x, y - 1) == 0) AddSpot(4, x, y);
                if (liq > 0 && (RdB(TileArr, x, y) & 0x60) != 0 && r.Next(4) == 0) AddSpot(5, x, y);
                if (active && (suffocate[type] || hot[type] || bleeding[type] || immediate[type] > 0)) AddSpot(8, x, y);
                if (!active && y > 200 && y < 1050 && (RdS(TileArr, x, y + 1) & 0x20) != 0 && r.Next(40) == 0) AddSpot(6, x, y);
                if (r.Next(2000) == 0) AddSpot(10, x, y);
            }
        }
        int sx = (int)SF(MainT, "spawnTileX"), sy = (int)SF(MainT, "spawnTileY");
        for (int i = 0; i < 400; i++) AddSpot(7, Math.Max(1, Math.Min(W - 2, sx + r.Next(-40, 41))), Math.Max(1, Math.Min(H - 42, sy + r.Next(-30, 31))));
        for (int i = 0; i < 2000; i++) AddSpot(9, StampX + r.Next(SW), StampY + r.Next(SH));
        for (int i = 0; i < Spots.Length; i++) Console.WriteLine("hotspots " + SpotNames[i] + ": " + Spots[i].Count);
        if (Spots[8].Count == 0) Spots[8].AddRange(Spots[9]);
        if (Spots[5].Count == 0) Spots[5].AddRange(Spots[9]);
    }
}
